1	export type QuoteResult = { premium: number };
2	
3	export type ClaimResult = { payout: number; remainingCap: number };
4	
5	export type StepResult = QuoteResult | ClaimResult;
6	
7	export type ScenarioResults = { results: StepResult[] };
8	
9	const PROCESSING_FEE = 5;
10	
11	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
12	
13	const LOYALTY_DISCOUNT_RATE = 0.2;
14	
15	const LOYALTY_THRESHOLD_YEARS = 2;
16	
17	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
18	
19	const ITEM_BASE_PREMIUM: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	  rune: 25,
25	  moonstone: 25,
26	};
27	
28	const ITEM_INSURANCE_VALUE: Record<string, number> = {
29	  sword: 1000,
30	  amulet: 600,
31	  staff: 800,
32	  potion: 400,
33	  rune: 250,
34	  moonstone: 250,
35	};
36	
37	type Item = { type: string; cursed?: boolean; enchantment?: number };
38	
39	// Steps are discriminated by `op`: a quote carries the items to insure, a claim
40	// carries damage entries against a policy an earlier quote step created.
41	type QuoteStep = { op: "quote"; items: Item[] };
42	
43	type Damage = { itemType: string; amount: number };
44	
45	type Incident = { cause: string; damages: Damage[] };
46	
47	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
48	
49	type Step = QuoteStep | ClaimStep;
50	
51	// Scenarios arrive as parsed JSON (from the CLI, and from object literals in
52	// the spec whose `op` widens to `string`), so the boundary type is deliberately
53	// wider than `Step`. Narrowing happens once, in `runStep`.
54	type StepInput = {
55	  op: string;
56	  items?: Item[];
57	  policy?: number;
58	  incident?: Incident;
59	};
60	
61	const isQuoteStep = (step: StepInput): step is QuoteStep =>
62	  step.op === "quote" && step.items !== undefined;
63	
64	const isClaimStep = (step: StepInput): step is ClaimStep =>
65	  step.op === "claim" && step.incident !== undefined && step.policy !== undefined;
66	
67	type Customer = { yearsWithMHPCO: number };
68	
69	type Scenario = { customer: Customer; steps: StepInput[] };
70	
71	const BLOCK_SIZE = 3;
72	
73	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
74	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
75	// a block either — "alike" means the same type, not the same family.
76	const BLOCK_BASE_PREMIUM = 60;
77	
78	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
79	
80	const countByType = (items: Item[]): Map<string, number> =>
81	  items.reduce(
82	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
83	    new Map<string, number>(),
84	  );
85	
86	const isBlock = (type: string, count: number): boolean =>
87	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
88	
89	const groupBasePremium = (type: string, count: number): number =>
90	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * ITEM_BASE_PREMIUM[type];
91	
92	const sum = (numbers: number[]): number =>
93	  numbers.reduce((total, value) => total + value, 0);
94	
95	const policyBasePremium = (items: Item[]): number =>
96	  sum(
97	    [...countByType(items)].map(([type, count]) =>
98	      groupBasePremium(type, count),
99	    ),
100	  );
101	
102	const CURSE_SURCHARGE_RATE = 0.5;
103	
104	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
105	
106	const HIGH_ENCHANTMENT_THRESHOLD = 5;
107	
108	const isCursed = (item: Item): boolean => item.cursed === true;
109	
110	const isHighlyEnchanted = (item: Item): boolean =>
111	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
112	
113	// Both surcharges can apply to the same item, so the rates add.
114	const itemSurchargeRate = (item: Item): number =>
115	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
116	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
117	
118	// Item-specific modifiers apply to the affected item's own base premium, not to
119	// the policy total — note that is the *ungrouped* base premium, so a cursed
120	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
121	const policyItemSurchargeTotal = (items: Item[]): number =>
122	  sum(
123	    items.map((item) => ITEM_BASE_PREMIUM[item.type] * itemSurchargeRate(item)),
124	  );
125	
126	const isLoyal = (customer: Customer): boolean =>
127	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
128	
129	// Policy-wide rates are summed rather than compounded, so a loyal customer's
130	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
131	// Every quote after the customer's first is a follow-up contract; the
132	// first-insurance surcharge still applies to it, since each item in a quote is
133	// treated as a first insurance regardless of customer history.
134	const policyModifierRate = (customer: Customer, isFollowUp: boolean): number =>
135	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
136	  (isFollowUp ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0) +
137	  FIRST_INSURANCE_SURCHARGE_RATE;
138	
139	const quoteStep = (
140	  step: QuoteStep,
141	  customer: Customer,
142	  isFollowUp: boolean,
143	): QuoteResult => {
144	  // Every modifier is a percentage of an *unmodified* base and they are all
145	  // summed, never compounded. Item surcharges are percentages of the affected
146	  // item's own base premium; policy-wide modifiers are percentages of the
147	  // policy base premium, which excludes those item surcharges. Summing the
148	  // rates before multiplying also keeps binary floating point out of trouble:
149	  // a compounded `base * (1 + rate)` chain drifts by ~1e-14, and Math.ceil
150	  // would turn that into a whole extra gold piece.
151	  const policyBase = policyBasePremium(step.items);
152	  const premiumBeforeFee =
153	    policyBase +
154	    policyItemSurchargeTotal(step.items) +
155	    policyBase * policyModifierRate(customer, isFollowUp);
156	
157	  // The fee is added after every percentage modifier, and only the final
158	  // premium is rounded — intermediates stay fractional.
159	  return { premium: Math.ceil(premiumBeforeFee + PROCESSING_FEE) };
160	};
161	
162	// A quote is a follow-up contract when the customer already holds one, i.e.
163	// when an earlier step in this scenario was itself a quote. Preceding claim
164	// steps do not make the next quote a follow-up.
165	const isFollowUpContract = (precedingSteps: StepInput[]): boolean =>
166	  precedingSteps.some(isQuoteStep);
167	
168	const DEDUCTIBLE_PER_DAMAGE = 100;
169	
170	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
171	
172	// The insurance sum is the plain sum of the items' insurance values; the block
173	// discount applies to the premium only, never to the sum insured.
174	const insuranceSum = (items: Item[]): number =>
175	  sum(items.map((item) => ITEM_INSURANCE_VALUE[item.type]));
176	
177	const damagePayout = (damage: Damage): number =>
178	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
179	
180	const claimStep = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
181	  const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(policyItems);
182	  // The deductible applies once per damaged item, so each damage entry is
183	  // reduced separately before the entries are summed.
184	  const payout = Math.floor(sum(step.incident.damages.map(damagePayout)));
185	
186	  return { payout, remainingCap: cap - payout };
187	};
188	
189	const runStep = (
190	  step: StepInput,
191	  customer: Customer,
192	  precedingSteps: StepInput[],
193	): StepResult => {
194	  if (isQuoteStep(step)) {
195	    return quoteStep(step, customer, isFollowUpContract(precedingSteps));
196	  }
197	  if (isClaimStep(step)) {
198	    const policy = precedingSteps[step.policy];
199	    if (policy === undefined || !isQuoteStep(policy)) {
200	      throw new Error(`Claim references a step that is not a quote`);
201	    }
202	    return claimStep(step, policy.items);
203	  }
204	  throw new Error(`Unsupported step op: ${step.op}`);
205	};
206	
207	export const runScenario = (scenario: Scenario): ScenarioResults => ({
208	  results: scenario.steps.map((step, index) =>
209	    runStep(step, scenario.customer, scenario.steps.slice(0, index)),
210	  ),
211	});
