// A policy pays out at most twice its insurance sum over its lifetime.
const policyCap = (items: Item[]): number =>
  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items);

const damagePayout = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

// The deductible applies once per damaged item, so each damage entry is
// reduced separately before the entries are summed.
const incidentPayout = (incident: Incident): number =>
  Math.floor(sum(incident.damages.map(damagePayout)));

const settleClaim = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = incidentPayout(step.incident);

  return { payout, remainingCap: policyCap(policyItems) - payout };
};
